arguments.command:
cd /tmp/vally-eval-trial-eUWcYC && P=.copilot-tracking/skraft-plans/pricing && D=2026-10-11 && mkdir -p $P/features $P/details/$D $P/evidence/$D/discount tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount
cat > $P/features/checkout-pricing-loyalty-discount.feature <<'EOF'
@loyalty-discount
Feature: Loyalty tier pricing

  A returning customer's loyalty tier reduces the basket subtotal at checkout.

  # SETTLED: Bronze, Silver and Gold (AC-1 to AC-4).
  # NOT DECIDED: Platinum. The business has not agreed a reduction, so there is
  # deliberately NO Platinum scenario and no expected value. Do not infer one.
  # It stays an open question for DISCUSS until an example is supplied.

  @happy-path @smoke
  Scenario: Bronze customer is charged the Bronze price for a basket
    Given a returning customer in the Bronze tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9500 cents

  @happy-path
  Scenario: Silver customer is charged the Silver price for a basket
    Given a returning customer in the Silver tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9000 cents

  @happy-path
  Scenario: Gold customer is charged the Gold price for a basket
    Given a returning customer in the Gold tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 8500 cents

  @edge-case
  Scenario: Bronze customer with a tiny basket has the reduction land on a whole cent in their favour
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents
EOF
cat > tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount/LoyaltyDiscountAcceptanceTests.cs <<'EOF'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class LoyaltyDiscountAcceptanceTests
{
    [Theory]
    // Bronze customer is charged the Bronze price for a basket
    [InlineData(LoyaltyTier.Bronze, 10000, 9500)]
    public void Returning_customer_is_charged_the_price_of_their_loyalty_tier(
        LoyaltyTier tier, int subtotalCents, int expectedChargedCents)
    {
        var useCase = new CalculateLoyaltyDiscount();

        var quote = useCase.Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier));

        Assert.Equal(expectedChargedCents, quote.TotalCents);
    }
}
EOF
dotnet test tests/CheckoutPricing.UnitTest --filter "FullyQualifiedName~LoyaltyDiscountAcceptanceTests" > $P/evidence/$D/discount/acceptance-red.stdout 2>&1; echo $? > $P/evidence/$D/discount/acceptance-red.exit; git rev-parse HEAD > $P/evidence/$D/discount/acceptance-red.rev; cat $P/evidence/$D/discount/acceptance-red.exit; tail -25 $P/evidence/$D/discount/acceptance-red.stdout

